<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {date,states} from './lib';
type Row=Record<string,any>;const props=defineProps<{rows:Row[],busy:boolean,canDelete:boolean,deleted:boolean}>();const emit=defineEmits<{status:[row:Row],remove:[row:Row],filter:[deleted:boolean]}>();
const search=ref(''),page=ref(0);const filtered=computed(()=>{const term=search.value.trim().toLowerCase();return props.rows.filter(c=>!term||[c.name,c.email,c.id].some(v=>String(v||'').toLowerCase().includes(term)))});const visible=computed(()=>filtered.value.slice(page.value*25,page.value*25+25));watch([search,()=>props.deleted,()=>props.rows],()=>{page.value=0});
</script>
<template><section class="panel customer-panel"><div class="section-head"><div><h2>账户列表</h2><p class="muted">审核、停用及恢复账户；删除账户会排队撤销代理权限，核账记录保留。</p></div><label v-if="canDelete" class="multi"><input type="checkbox" :checked="deleted" :disabled="busy" @change="emit('filter',($event.target as HTMLInputElement).checked)">显示已删除用户</label></div><label class="customer-search">搜索当前列表<input v-model="search" type="search" placeholder="昵称、邮箱或用户 ID" maxlength="160"></label><p class="muted">匹配 {{filtered.length}} 位 · 本次读取最近 {{rows.length}} 位，最多 500 位</p><div class="customer-grid-head" aria-hidden="true"><span>用户</span><span>状态</span><span>注册时间</span><span>操作</span></div><article v-for="c in visible" :key="c.id" class="customer-record"><div class="customer-identity"><strong>{{c.name}}</strong><span>{{c.email}}</span><details><summary>用户 ID</summary><small class="mono">{{c.id}}</small></details></div><span class="customer-status badge">{{c.deleted_at?'已删除':states[c.status]||c.status}}</span><div class="customer-date"><small>注册时间</small>{{date(c.created_at)}}</div><div class="customer-actions"><button v-if="!c.deleted_at&&c.role!=='admin'&&c.email_verified_at" :disabled="busy" @click="emit('status',c)">{{c.status==='active'?'停用账户':'批准 / 恢复'}}</button><span v-if="!c.deleted_at&&!c.email_verified_at" class="muted">等待邮箱验证</span><button v-if="canDelete" :disabled="busy" @click="emit('remove',c)">{{c.deleted_at?'恢复用户':'删除用户'}}</button></div></article><p v-if="!visible.length" class="empty">暂无匹配用户</p><div v-if="filtered.length>25" class="customer-pages"><button :disabled="page===0" @click="page--">上一页</button><span>{{page+1}} / {{Math.ceil(filtered.length/25)}}</span><button :disabled="(page+1)*25>=filtered.length" @click="page++">下一页</button></div></section></template>
<style scoped>.customer-panel{overflow:hidden}.customer-panel .section-head{align-items:center}.customer-panel .section-head h2{margin-bottom:8px}.customer-search{max-width:460px}.customer-grid-head,.customer-record{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(80px,.55fr) minmax(140px,1fr) minmax(200px,1.1fr);gap:18px;align-items:center}.customer-grid-head{padding:12px 0;color:var(--muted);font-size:12px;border-bottom:1px solid var(--border)}.customer-record{padding:18px 0;border-bottom:1px solid var(--border)}.customer-identity{min-width:0;display:grid;gap:4px;overflow-wrap:anywhere}.customer-identity>span{font-size:12px;color:var(--muted)}.customer-identity details{font-size:10px;color:var(--muted)}.customer-identity summary{cursor:pointer}.customer-status{justify-self:start}.customer-date{font-size:12px;overflow-wrap:anywhere}.customer-date>small{display:none}.customer-actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center;justify-content:flex-end}.customer-actions button{font-size:12px;min-height:38px}.customer-pages{display:flex;align-items:center;justify-content:center;gap:14px;margin-top:20px}@media(max-width:1200px){.customer-grid-head,.customer-record{grid-template-columns:minmax(0,1.5fr) minmax(72px,.5fr) minmax(130px,1fr);gap:12px}.customer-grid-head>span:last-child{display:none}.customer-actions{grid-column:1/-1;justify-content:flex-start}}@media(max-width:760px){.customer-grid-head{display:none}.customer-record{grid-template-columns:minmax(0,1fr) auto;gap:12px}.customer-date{grid-column:1/-1;display:flex;gap:10px;align-items:center}.customer-date>small{display:inline}.customer-actions button{min-height:42px}.customer-panel .section-head{align-items:flex-start}.customer-identity strong{font-size:15px}.customer-record:last-child{border-bottom:0}}
</style>
